"""Hematology (anemias, leukemias, lymphomas) and sarcoidosis topics for internal medicine (Harrison 22e)."""
from common import Topic

SRC = "Harrison 22e"
FAM = "המטולוגיה"


def topics():
    T = []

    t = Topic("anem", "גישה לאנמיה", "Approach to Anemia", FAM, SRC, """
<h4>הגדרה (WHO)</h4><ul><li>המוגלובין מתחת ל-13 g/dL בגברים ומתחת ל-12 g/dL בנשים.</li></ul>
<h4>שלב 1: רטיקולוציטים</h4><ul><li>Reticulocyte production index = רטיקולוציטים (%) × (Hct/45) ÷ פקטור הבשלה.</li><li>מעל 2-2.5: תגובה מתאימה של מח העצם (דימום, המוליזה). מתחת ל-2: אנמיה היפופרוליפרטיבית או הפרעת הבשלה.</li></ul>
<h4>שלב 2: MCV</h4><ul><li>מיקרוציטית (מתחת ל-80): חוסר ברזל, תלסמיה, אנמיה של מחלה כרונית (לעיתים), סידרובלסטית, הרעלת עופרת.</li><li>נורמוציטית: מחלה כרונית, CKD (חוסר EPO), דימום חריף, המוליזה, מח עצם.</li><li>מקרוציטית (מעל 100): מגלובלסטית (B12, חומצה פולית, תרופות: מתוטרקסט, הידרוקסיאוריאה, AZT), לא מגלובלסטית (אלכוהול, כבד, היפותירואידיזם, MDS, רטיקולוציטוזיס).</li></ul>
<h4>עזרים</h4><ul><li>Mentzer index = MCV ÷ RBC (במיליונים). מתחת ל-13: תלסמיה. מעל 13: חוסר ברזל.</li><li>RDW גבוה: חוסר ברזל, אנמיה מעורבת. תקין: תלסמיה טריט.</li></ul>
""", ["anemia", "MCV", "reticulocyte"])
    t.N("מתחת לאיזו רמת המוגלובין (g/dL) מוגדרת אנמיה בגבר לפי WHO?", 13, 0, "g/dL")
    t.N("מתחת לאיזו רמת המוגלובין (g/dL) מוגדרת אנמיה באישה לא בהריון לפי WHO?", 12, 0, "g/dL")
    t.F("מה מראה reticulocyte production index מעל 2-2.5, ומה מתחת ל-2?", "מעל 2-2.5: מח העצם מגיב כראוי (דימום או המוליזה). מתחת ל-2: אנמיה היפופרוליפרטיבית או הפרעת הבשלה.")
    t.F("מנה 5 סיבות לאנמיה מיקרוציטית.", "חוסר ברזל, תלסמיה, אנמיה של מחלה כרונית, אנמיה סידרובלסטית, הרעלת עופרת.")
    t.F("מנה סיבות לאנמיה מקרוציטית לא מגלובלסטית.", "אלכוהול, מחלת כבד, היפותירואידיזם, MDS, רטיקולוציטוזיס.")
    t.M("MCV 66, RBC 6.0 מיליון, RDW תקין. מה האבחנה הסבירה?", ["חוסר ברזל", "תלסמיה טריט", "אנמיה של מחלה כרונית", "אנמיה סידרובלסטית"], 1, "Mentzer = 66/6 = 11, מתחת ל-13, ו-RDW תקין.")
    t.N("מהו ערך הסף של Mentzer index שמתחתיו חושדים בתלסמיה?", 13, 0, "")
    T.append(t)

    t = Topic("ida", "אנמיה מחוסר ברזל ואנמיה של מחלה כרונית", "Iron Deficiency Anemia & Anemia of Inflammation", FAM, SRC, """
<h4>חוסר ברזל</h4><ul><li>הסיבה השכיחה לאנמיה בעולם. בנשים בגיל הפוריות: וסת והריון. בגברים ובנשים אחרי גיל המעבר: דימום ממערכת העיכול עד שיוכח אחרת (גסטרוסקופיה וקולונוסקופיה).</li><li>גם: צליאק, H. pylori, ניתוח בריאטרי, PPI.</li><li>מעבדה: פריטין נמוך (מתחת ל-30 ng/mL; מתחת ל-15 כמעט אבחנתי), סטורציית טרנספרין מתחת ל-20%, TIBC גבוה, RDW גבוה, טרומבוציטוזיס.</li><li>פריטין הוא חלבון שלב חריף: עלול להיות תקין בדלקת למרות חוסר.</li><li>קליניקה: Pica (בעיקר קרח), קוילוניכיה, Plummer-Vinson (קרום בוושט, דיספגיה, גלוסיטיס).</li><li>טיפול: ברזל פומי (מינון כל יומיים משפר ספיגה), עם ויטמין C. ברזל IV בתת-ספיגה, אי-סבילות, IBD, CKD. רטיקולוציטוזיס אחרי כשבוע. ממשיכים 3-6 חודשים אחרי תיקון ההמוגלובין למילוי מאגרים.</li></ul>
<h4>אנמיה של מחלה כרונית / דלקת</h4><ul><li>הפסידין מוגבר (IL-6) חוסם את ferroportin: ברזל "כלוא" במקרופאגים.</li><li>פריטין תקין או גבוה, TIBC נמוך, סטורציה נמוכה. לרוב נורמוציטית, לעיתים מיקרוציטית קלה.</li><li>sTfR: גבוה בחוסר ברזל, תקין במחלה כרונית.</li></ul>
""", ["iron", "ferritin", "hepcidin", "ACD"])
    t.N("מתחת לאיזו רמת פריטין (ng/mL) נחשב החוסר לכמעט ודאי?", 15, 0, "ng/mL")
    t.M("מה הצעד הנכון בגבר בן 60 עם אנמיה מחוסר ברזל ללא סיבה ברורה?", ["ברזל פומי ומעקב", "גסטרוסקופיה וקולונוסקופיה", "בדיקת מח עצם", "CT בטן בלבד"], 1)
    t.F("איך מבדילים במעבדה בין חוסר ברזל לאנמיה של מחלה כרונית?", "חוסר ברזל: פריטין נמוך, TIBC גבוה, sTfR גבוה. מחלה כרונית: פריטין תקין/גבוה, TIBC נמוך, sTfR תקין.")
    t.F("מהו המנגנון של אנמיה של מחלה כרונית?", "IL-6 מעלה הפסידין, שמפרק את ferroportin. הברזל נלכד במקרופאגים ובאנטרוציטים ואינו זמין לייצור דם.")
    t.F("מהי תסמונת Plummer-Vinson?", "חוסר ברזל, דיספגיה עקב קרומים (webs) בוושט העליון, וגלוסיטיס. סיכון מוגבר לסרטן תאי קשקש של הוושט.")
    t.F("כמה זמן ממשיכים ברזל פומי אחרי שההמוגלובין חזר לנורמה?", "3-6 חודשים נוספים, למילוי המאגרים.")
    t.N("מתחת לאיזו סטורציית טרנספרין (%) תומכת בחוסר ברזל?", 20, 0, "%")
    T.append(t)

    t = Topic("thal", "תלסמיות", "Thalassemias", FAM, SRC, """
<h4>אלפא תלסמיה (4 גנים)</h4><ul><li>חסר גן אחד: נשא שקט.</li><li>2 גנים: α-thal trait, מיקרוציטוזיס קלה. אלקטרופורזה תקינה.</li><li>3 גנים: HbH disease (β4). המוליזה, ספלנומגליה, Heinz bodies.</li><li>4 גנים: Hb Bart's (γ4), הידרופס עוברי.</li><li>מחיקה ב-cis (שכיח באסיאתים) מגדילה את הסיכון לצאצא עם 4 מחיקות.</li></ul>
<h4>בטא תלסמיה</h4><ul><li>טריט (מינור): מיקרוציטוזיס, HbA2 מעל 3.5%. RBC גבוה, RDW תקין.</li><li>מז׳ור (Cooley): מופיעה בגיל 6-12 חודשים (מעבר מ-HbF). אנמיה קשה תלוית עירויים, המטופואזה חוץ-מח-עצמית ("hair on end" בגולגולת, chipmunk facies), ספלנומגליה.</li><li>אינטרמדיה: לא תלוית עירויים באופן קבוע.</li></ul>
<h4>טיפול ומעקב</h4><ul><li>עירויים קבועים + קלציה (דפרוקסאמין, דפראסירוקס, דפריפרון). מעקב פריטין ו-MRI T2* ללב ולכבד.</li><li>עודף ברזל: אי-ספיקת לב (סיבת המוות העיקרית), סוכרת, היפוגונדיזם, שחמת.</li><li>ספלנקטומיה בהיפרספלניזם. HSCT ריפוי, וטיפול גנטי. Luspatercept מפחית צורך בעירויים.</li><li>לא לתת ברזל בתלסמיה טריט.</li></ul>
""", ["thalassemia", "HbA2", "HbH"])
    t.N("מעל איזו רמת HbA2 (%) אבחנתי לבטא תלסמיה טריט?", 3.5, 0, "%")
    t.F("תאר את 4 הדרגות של אלפא תלסמיה לפי מספר הגנים החסרים.", "1: נשא שקט. 2: α-thal trait (מיקרוציטוזיס קלה). 3: HbH disease (β4, המוליזה). 4: Hb Bart's (γ4), הידרופס עוברי.")
    t.M("מה מרכיב ההמוגלובין ב-HbH disease?", ["γ4", "β4", "α2δ2", "α2γ2"], 1)
    t.N("באיזה גיל (חודשים) מופיעה בדרך כלל בטא תלסמיה מז׳ור? (ערך מרכזי)", 6, 3, "חודשים")
    t.F("מהי סיבת המוות העיקרית בבטא תלסמיה מז׳ור?", "אי-ספיקת לב והפרעות קצב עקב עודף ברזל בשריר הלב.")
    t.F("מה המשמעות של אלקטרופורזה תקינה במטופל עם מיקרוציטוזיס, ברזל תקין ו-Mentzer נמוך?", "חשד לאלפא תלסמיה טריט (2 גנים). האבחנה בבדיקה גנטית.")
    t.M("איזו בדיקה עוקבת אחרי עודף ברזל בלב?", ["אקו לב", "MRI T2*", "פריטין בלבד", "ביופסיית לב"], 1)
    T.append(t)

    t = Topic("mega", "אנמיה מגלובלסטית: B12 וחומצה פולית", "Megaloblastic Anemia (B12 & Folate)", FAM, SRC, """
<h4>ממצאים משותפים</h4><ul><li>מקרוציטוזיס (לרוב MCV מעל 110), נויטרופילים היפרסגמנטיים (5 אונות ומעלה), פנציטופניה, LDH ובילירובין עקיף גבוהים (המטופואזה לא יעילה).</li></ul>
<h4>B12</h4><ul><li>מאגרים ל-3-5 שנים.</li><li>סיבות: אנמיה מזיקה (השכיחה; נוגדנים ל-intrinsic factor ספציפיים, נוגדנים לתאי parietal רגישים), גסטרקטומיה, ניתוח בריאטרי, מחלה באילאום הטרמינלי (Crohn, כריתה), טבעונות, מטפורמין, PPI, תולעת Diphyllobothrium latum, SIBO.</li><li>נוירולוגיה: Subacute combined degeneration (עמודות אחוריות ומסילות קורטיקוספינליות לטרליות): הפרעה בתחושת רטט ומנח, אטקסיה, ספסטיות, Babinski. גם דמנציה ונוירופתיה. יכולה להופיע בלי אנמיה.</li><li>מעבדה: גם MMA וגם הומוציסטאין גבוהים.</li><li>אנמיה מזיקה: סיכון מוגבר לסרטן קיבה וגידולים קרצינואידים.</li><li>טיפול: B12 IM (או פומי במינון גבוה). היפוקלמיה אפשרית בתחילת הטיפול.</li></ul>
<h4>חומצה פולית</h4><ul><li>מאגרים לכ-4 חודשים.</li><li>סיבות: תזונה (אלכוהוליזם), הריון, המוליזה כרונית, תרופות (מתוטרקסט, פניטואין, טרימתופרים), צליאק.</li><li>הומוציסטאין גבוה, MMA תקין. אין נזק נוירולוגי.</li><li>אסור לתת חומצה פולית לבד בחוסר B12: מתקנת את האנמיה אבל הנזק הנוירולוגי מתקדם.</li></ul>
""", ["B12", "folate", "pernicious anemia", "MMA"])
    t.F("איך MMA והומוציסטאין מבדילים בין חוסר B12 לחוסר חומצה פולית?", "חוסר B12: שניהם גבוהים. חוסר חומצה פולית: רק הומוציסטאין גבוה, MMA תקין.")
    t.F("מהי subacute combined degeneration?", "פגיעה בעמודות האחוריות (תחושת רטט ומנח, אטקסיה) ובמסילות הקורטיקוספינליות הלטרליות (חולשה, ספסטיות, Babinski) בחוסר B12.")
    t.M("איזה נוגדן ספציפי ביותר לאנמיה מזיקה?", ["Anti-parietal cell", "Anti-intrinsic factor", "Anti-TPO", "Anti-tTG"], 1)
    t.N("למשך כמה שנים מספיקים מאגרי B12 (ערך מרכזי)?", 4, 1, "שנים")
    t.N("מכמה אונות ומעלה נויטרופיל נחשב היפרסגמנטי?", 5, 0, "אונות")
    t.F("למה אסור לתת חומצה פולית לבד בחוסר B12?", "החומצה הפולית מתקנת את האנמיה, אבל הנזק הנוירולוגי ממשיך ומחמיר.")
    t.M("איזו תרופה לסוכרת גורמת לחוסר B12?", ["גליקלזיד", "מטפורמין", "אינסולין", "סיטגליפטין"], 1)
    t.F("מנה 3 תרופות שגורמות לחוסר בחומצה פולית.", "מתוטרקסט, פניטואין, טרימתופרים.")
    T.append(t)

    t = Topic("hemol", "אנמיות המוליטיות", "Hemolytic Anemias", FAM, SRC, """
<h4>מעבדה של המוליזה</h4><ul><li>LDH גבוה, בילירובין עקיף גבוה, הפטוגלובין נמוך, רטיקולוציטוזיס. תוך-וסקולרית: המוגלובינוריה והמוסידרינוריה.</li><li>Coombs ישיר (DAT): חיובי במחלה חיסונית.</li></ul>
<h4>AIHA</h4><ul><li>חם (IgG, הסוג השכיח): ספרוציטים, המוליזה בטחול. סיבות: אידיופתי, CLL, SLE, תרופות. טיפול: סטרואידים, ריטוקסימאב, ספלנקטומיה.</li><li>קר (IgM, משלים): אגלוטינציה בקור, אקרוציאנוזיס. סיבות: Mycoplasma, EBV, לימפומה. טיפול: להימנע מקור, ריטוקסימאב, Sutimlimab. סטרואידים וספלנקטומיה לא יעילים.</li></ul>
<h4>G6PD</h4><ul><li>X-linked. המוליזה תוך-וסקולרית אחרי חשיפה: פול (פאביזם), זיהומים, תרופות (פרימקווין, דפסון, סולפונאמידים, ניטרופורנטואין, רסבוריקאז).</li><li>משטח: Heinz bodies, bite cells. בזמן המוליזה חריפה רמת האנזים יכולה להיות תקינה כוזבת: לבדוק שוב אחרי 2-3 חודשים.</li></ul>
<h4>ספרוציטוזיס תורשתית</h4><ul><li>לרוב אוטוזומלית דומיננטית (אנקירין, ספקטרין). MCHC גבוה, ספרוציטים, Coombs שלילי. אבחנה: EMA binding / שבירות אוסמוטית.</li><li>ספלנומגליה, אבני מרה פיגמנטיות, משבר אפלסטי עם Parvovirus B19. ספלנקטומיה במחלה קשה.</li></ul>
<h4>PNH</h4><ul><li>מוטציה נרכשת ב-PIGA: חוסר CD55/CD59 (אבחנה ב-flow). המוליזה תוך-וסקולרית, תרומבוזות בורידים לא אופייניים (Budd-Chiari), כשל מח עצם. טיפול: מעכבי C5 (אקוליזומאב) עם חיסון למנינגוקוק.</li></ul>
<h4>MAHA</h4><ul><li>TTP, HUS, DIC, מסתם תותב: שיסטוציטים. TTP: ADAMTS13 מתחת ל-10%, טיפול בפלזמפרזיס דחוף.</li></ul>
""", ["AIHA", "G6PD", "spherocytosis", "PNH", "Coombs"])
    t.F("מהן בדיקות המעבדה שמעידות על המוליזה?", "LDH גבוה, בילירובין עקיף גבוה, הפטוגלובין נמוך, רטיקולוציטוזיס.")
    t.F("מה ההבדלים בין AIHA חם לקר?", "חם: IgG, המוליזה בטחול, ספרוציטים, CLL/SLE/תרופות, מגיב לסטרואידים. קר: IgM ומשלים, אגלוטינציה, Mycoplasma/EBV/לימפומה, לא מגיב לסטרואידים.")
    t.M("איזה ממצא במשטח אופייני ל-G6PD?", ["ספרוציטים", "Bite cells ו-Heinz bodies", "Target cells", "Tear drop cells"], 1)
    t.F("למה רמת G6PD יכולה להיות תקינה בזמן המוליזה חריפה?", "התאים הוותיקים, החסרים באנזים, כבר עברו המוליזה, והרטיקולוציטים הצעירים עשירים ב-G6PD. בודקים שוב אחרי 2-3 חודשים.")
    t.M("איזו בדיקה מאבחנת PNH?", ["Coombs", "Flow cytometry ל-CD55/CD59", "EMA binding", "אלקטרופורזה"], 1)
